const GM_ROWS = (function(){
  const rows = GM_RANKING_RAW.map(a => ({
    n:a[0], s:a[1], name:a[2], memo:a[3], genre:a[4], genres:[a[4]].concat(a[6] || []), dup:a[5] || '',
    raw:(a[2] + ' ' + a[3]).trim(), repeat:false
  }));
  const first = {};
  rows.forEach(r => { if(r.dup){ if(first[r.dup] == null) first[r.dup] = r.n; else r.repeat = true; } });
  return rows;
})();

const GM_GENRES = Array.from(new Set(GM_ROWS.flatMap(r => r.genres)));   // 1行に複数のジャンルを付けられる（先頭が主ジャンル）

function gmShopKey(r){ return r.dup ? 'd:' + r.dup : 'n:' + r.n; }
function gmDistinctShops(list){ return new Set(list.map(gmShopKey)).size; }

