/* 旧カテゴリーkeyで保存済みのコラムを、新しいカテゴリーへ読み替える */
const GM_CAT_ALIAS = { five:'kokozo', men:'hitori', dup:'gatsuri', noge:'katari', tori:'katari', chuka:'nakama', minato:'lunch', ensei:'toku', kannai:'yokohama', clock:'lunch' };

function gmCategoryStats(){
  return GM_CATEGORIES.map(c => {
    const items = GM_ROWS.filter(c.match);
    const shops = gmDistinctShops(items);
    const o = Object.assign({}, c, { items, rows:items.length, shops, label:c.name + ' ' + shops + '軒' });
    return (typeof gmL10nCat === 'function') ? gmL10nCat(o) : o;   // 多言語（i18n.js があるときだけ）
  });
}

/* コラムに付くカテゴリ表示情報 */
function gmCategoryOf(col){
  if(col.catKey){
    const k = GM_CAT_ALIAS[col.catKey] || col.catKey;
    const c = gmCategoryStats().find(x => x.key === k);
    if(c) return { key:c.key, name:c.name, label:c.label, tone:c.tone };
  }
  const name = col.category || 'その他';
  const label = col.catCount ? name + ' ' + col.catCount + (/[軒件本]$/.test(String(col.catCount)) ? '' : '軒') : name;
  return { key:'', name, label, tone:col.catTone || 'indigo' };
}


